mapper.select:
	SELECT  

	FROM fw_litigate_dispute AS d 
  LEFT JOIN () AS ourside ON 
    ourside.fk_Dispute_ID = d.f_ID
  LEFT JOIN () AS opposite ON
    opposite.fk_Dispute_ID = d.f_ID
  LEFT JOIN () AS progress ON
  	progress.fk_Dispute_ID = d.f_ID
  LEFT JOIN () AS cnt ON 
  	cnt.fk_Dispute_ID = d.f_ID

		d.f_IsDel = 0

      AND d.fk_Reported_Org_ID = #{bo.orgId }


      AND d.f_Status = #{bo.status }



      AND d.f_Name LIKE #{name }



      AND d.f_Code LIKE #{code }



        AND d.f_Status IN (1, 7, 8)


        AND d.f_Status NOT IN (1, 7, 8)



      AND d.f_Is_Foreign_Related = #{bo.isForeignRelated }


      AND d.f_Incident_Date >= #{bo.begindate }


      AND d.f_Incident_Date <= #{bo.enddate }


      AND d.f_Type = #{bo.type }


      AND d.f_Is_External = #{bo.isExternal }


      AND d.f_Settle_Method = #{bo.settleMethod }


      AND d.f_ID IN (
        SELECT ooo.fk_Dispute_Id 
        FROM fw_litigate_dispute_ourside AS ooo
        WHERE ooo.f_IsDel = 0


            AND ooo.f_Litigant_Name LIKE #{oursideName }



          AND ooo.fk_Org_Name LIKE #{agencyName }

      )



      AND d.f_ID IN (
        SELECT oppo.fk_Dispute_ID
        FROM fw_litigate_dispute_opposite AS oppo
        WHERE oppo.f_IsDel = 0
        AND oppo.f_Name LIKE #{oppositeName}
      )


      AND d.f_ID IN (
        SELECT prog.fk_Dispute_ID 
        FROM fw_litigate_dispute_progress AS prog
        WHERE prog.f_IsDel = 0

          AND prog.f_Receiving_Agency = #{bo.receivingAgency }


          AND prog.f_Step = #{bo.step }


          AND prog.f_Status = #{bo.progressStatus }

      )


      AND d.f_Settle_Date >= #{bo.closeDateBegin }


      AND d.f_Settle_Date <= #{bo.closeDateEnd }


      AND d.f_Related_Amount >= #{bo.relatedAmountMin }


      AND d.f_Related_Amount <= #{bo.relatedAmountMax }


      AND d.f_Estimated_Loss_Amount >= #{bo.estimatedLossAmountMin }


      AND d.f_Estimated_Loss_Amount <= #{bo.estimatedLossAmountMax }


      AND d.f_Is_Debt_Collection = #{bo.isDebtCollection }


      AND d.f_Is_Criminal_Involved = #{bo.isCriminalInvolved }


      AND d.f_ID IN (
        SELECT sed.fk_Dispute_ID 
        FROM fw_litigate_dispute_settled AS sed
        WHERE sed.f_IsDel = 0

          AND sed.f_Loss_Recovered >= #{bo.lossRecoveredMin }


          AND sed.f_Loss_Recovered <= #{bo.lossRecoveredMax }


          AND sed.f_Loss_Avoided >= #{bo.lossAvoidedMin }


          AND sed.f_Loss_Avoided <= #{bo.lossAvoidedMax }

      )



        AND d.f_Is_Discard = #{bo.isDiscarded }


        AND d.f_Is_Discard = 0


    AND (d.fk_Reported_Org_ID IN 

    	#{item}


      OR d.fk_Reported_Org_ID IN

        #{item}


    )
